use vstd::prelude::*;

verus! {
    fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> (result: Vec<f32>)
        requires
            a.len() == mask.len(),
            values.len() > 0,
        ensures
            result.len() == a.len(),
            forall |i: nat| 0 <= i < a.len() ==> 
                (mask[i] ==> result[i] == values[i % values.len()]) &&
                (!mask[i] ==> result[i] == a[i]),
    {
        let mut result: Vec<f32> = vec![0.0; a.len()]; // Initialize result array

        let n = a.len() as nat; // Length of the input array
        let mut i: nat = 0; // Index variable

        while i < n
            invariant
                0 <= i <= n,
                result.len() == a.len(),
                forall |j: nat| 0 <= j < i ==> 
                    (mask[j] ==> result[j] == values[j % values.len()]) &&
                    (!mask[j] ==> result[j] == a[j]),
            decreases n - i,
        {
            if mask[i] {
                result[i] = values[i % values.len()]; // Use replacement value
            } else {
                result[i] = a[i]; // Use original value
            }
            i = i + 1; // Increment index
        }

        result // Return the constructed result array
    }
}
